# ===================================================================== 54
add(id=54, title="Qualitative evidence synthesis", last_verified=V, prerequisites=["Modules 9, 13, 17"],
 objectives=["Decide when a qualitative or mixed-methods synthesis answers the question better than a meta-analysis.", "Describe thematic synthesis and the main alternatives, and how GRADE-CERQual rates confidence in findings.", "Report qualitative syntheses transparently (ENTREQ)."],
 why="Questions about experiences, acceptability, mechanisms and implementation cannot be answered by pooled effect sizes. Qualitative synthesis is a rigorous method with its own standards - not 'meta-analysis without numbers'.",
 plain="""A **qualitative evidence synthesis (QES)** systematically combines findings from primary qualitative studies (interviews, focus groups, open-ended responses). Thomas & Harden (2008) describe **thematic synthesis**: (1) line-by-line coding of the findings sections, (2) organising codes into **descriptive themes** that stay close to the primary studies, (3) developing **analytical themes** that go beyond them to generate new interpretations. Other approaches (meta-ethnography, framework synthesis, realist synthesis - Module 56) differ in how much they interpret versus aggregate. Qualitative synthesis is chosen when the review question is about *how* or *why*, or about perceptions, not *how much*.""",
 intermediate="""**Search and sampling:** qualitative searching is harder (indexing is poor); sampling can be purposive or exhaustive but must be justified. **Quality appraisal:** structured tools (e.g. CASP-type checklists) support transparency; there is no consensus about excluding studies on quality. **Confidence in findings:** GRADE-CERQual (Lewin et al. 2018 series) assesses four components - methodological limitations, coherence, adequacy of data and relevance - to rate confidence in each synthesised finding. **Reporting:** ENTREQ (Tong et al. 2012) lists items to report; PRISMA-style flow diagrams apply to the study selection. **Reliability:** coding by two people with discussion; kappa is sometimes used for screening decisions but is not a measure of validity for interpretative coding. **Integration with quantitative evidence** (mixed-methods reviews) can explain heterogeneity in effects (e.g. coding implementation factors).""",
 advanced="""Interpretative methods acknowledge the reviewer's position (reflexivity); 'replicability' means a transparent audit trail from findings to primary data, not identical themes. Software (NVivo, MAXQDA, Taguette, spreadsheets) supports coding but does not do the synthesis. For a laboratory biologist, qualitative synthesis is usually relevant to *context*: e.g. researchers' practices in randomisation and blinding of animal studies, or barriers to data sharing - not to the biological effect question.""",
 assumptions=["The research question is interpretive, not estimative.", "Primary studies are of sufficient richness (thick data) for synthesis.", "Coding decisions are documented and traceable."],
 formulas=[dict(name="Cohen's kappa (for screening agreement)", tex=r"\kappa=\frac{p_o-p_e}{1-p_e}", symbols={"p_o":"observed agreement","p_e":"agreement expected by chance"})],
 worked_example="""Two reviewers code 20 excerpts as 'barrier' (yes) or 'not a barrier' (no): 9 both yes, 7 both no, 2 yes/no and 2 no/yes. Observed agreement p_o = 16/20 = **0.80**; expected agreement p_e = 0.55×0.55 + 0.45×0.45 = **0.505**; κ = (0.80 − 0.505)/(1 − 0.505) = **0.596** ('moderate' by the Landis-Koch convention, which is a convention and not a validity threshold). Kappa checks consistency of a *screening or coding decision*; it does not show that the themes are right.""",
 examples=[("Preclinical","Researchers' reasons for not blinding animal experiments."),("Clinical","Patients' experiences of treatment."),("Ecology","Stakeholder views on management."),("Genetics","Ethical views on data sharing."),("Education","Teachers' implementation barriers.")],
 mistakes=["Counting how many studies mention a theme as if it were prevalence.","Skipping the audit trail from finding to source.","Using a meta-analysis question for a qualitative design.","Reporting no appraisal or reflexivity."],
 misconceptions=[("'Qualitative synthesis is subjective, so rigour is irrelevant.'","Transparent coding, appraisal and confidence rating are expected."),("'High kappa means valid themes.'","It measures agreement, not truth.")],
 controversies=["Whether to exclude low-quality qualitative studies.", "Aggregative vs interpretative synthesis.", "Use of kappa in qualitative coding."],
 decision_tree=[("Question about experiences or mechanisms?","Qualitative synthesis."),("Question about effect size?","Meta-analysis."),("Both?","Mixed-methods review with a clear integration plan.")],
 exercises=["Write a qualitative review question and justify why it is not a meta-analysis question.", "Compute kappa for your own two-coder pilot.", "List the CERQual components for one finding."],
 integrity="Keep an audit trail from each theme to quoted data and to the primary study; do not generalise beyond the sampled studies.", further=["thomas2008","tong2012","lewin2018cerqual","cohen1960"],
 coding=dict(r='po <- 16/20; pe <- 0.55 * 0.55 + 0.45 * 0.45\n(po - pe) / (1 - pe)   # 0.596', python='from metalab import workflow as W\nr1=[1]*9+[1]*2+[0]*2+[0]*7; r2=[1]*9+[0]*2+[1]*2+[0]*7\nprint(W.cohens_kappa(r1, r2)["kappa"])'),
 application="**Milestone 1/3:** decide whether a qualitative or mixed-methods component is part of your question; if not, state why.", checklist=["Question type matched to method","Coding documented","Appraisal done","ENTREQ followed"],
 quiz=[dict(q="κ for 9/7 agreements and 2/2 disagreements among 20 items?", opts=["0.596","0.80","0.505","0.25"], ans=0, why="(0.80−0.505)/(1−0.505).", numeric=True),
  dict(q="Thematic synthesis has how many stages?", opts=["Three (coding, descriptive themes, analytical themes)","One","Five","None"], ans=0, why="Thomas & Harden 2008."),
  dict(q="GRADE-CERQual rates...", opts=["Confidence in qualitative review findings","Effect sizes","Heterogeneity","Publication bias"], ans=0, why="Lewin 2018."),
  dict(q="Counting how many studies mention a theme...", opts=["Does not measure prevalence in the population","Is prevalence","Is effect size","Is validity"], ans=0, why="Sampling is not representative."),
  dict(q="ENTREQ is...", opts=["A reporting guideline for qualitative syntheses","A risk-of-bias tool","A statistic","A database"], ans=0, why="Tong 2012.")])

# ===================================================================== 56
add(id=56, title="Umbrella, rapid, living and realist reviews", last_verified=V, prerequisites=["Modules 9, 13, 14, 15"],
 objectives=["Choose among umbrella, rapid, living and realist reviews and state each design's limits.", "Handle overlap of primary studies in umbrella reviews (corrected covered area).", "Plan updating and versioning for a living review."],
 why="Not every question needs a conventional systematic review, and not every systematic review can be done quickly or once. Choosing the wrong variant produces either unjustifiable shortcuts or needless work.",
 plain="""An **umbrella review** (review of reviews; Aromataris et al. 2015) summarises evidence from existing systematic reviews, usually of a broad question; its main problem is **overlap** - the same primary study appears in several reviews and is counted more than once. A **rapid review** simplifies steps (fewer databases, single screening with verification, restricted time/language) to deliver quickly; the Cochrane Rapid Reviews Methods Group provides guidance (Garritty et al. 2021) and stresses transparency about shortcuts. A **living systematic review** is continually updated as evidence appears (Elliott et al. 2014): it requires a process for surveillance, updating and version control. A **realist review** explains *what works for whom, in what circumstances and why* using context-mechanism-outcome configurations; reporting follows the RAMESES standards (Wong et al. 2013).""",
 intermediate="""**Overlap:** the **corrected covered area (CCA)** = (N − r)/(r·c − r) with N the total number of inclusions (double counting), r the number of unique primary studies and c the number of reviews; larger values mean more overlap (Pieper et al. 2014 introduced this overlap measure for overviews). Report CCA and handle overlap by choosing one review per question or analysing unique studies. **Rapid reviews:** list every deviation from the full systematic process and its likely effect on completeness/bias; do not call a review 'systematic' if essential steps were skipped. **Living reviews:** define triggers (new RCTs, monthly alerts), version numbering, retirement criteria and how changes in conclusions are communicated; registration records and a changelog are central. **Realist reviews:** iterative, theory-driven; not a replacement for effect estimation. **Protocol registration** (Booth et al. 2012; Pieper et al. 2022 on where to register) applies to many of these variants.""",
 advanced="""Quality of included reviews is assessed with tools such as AMSTAR 2 (not covered here). Re-analysing individual studies across overlapping reviews risks inconsistent data extraction; an umbrella review should not re-pool unless methods are aligned. For a first paper, a conventional systematic review of primary studies is usually the cleanest design; the variants here are things to *recognise and appraise* before you *produce* them.""",
 assumptions=["Reviews included in an umbrella review are comparable in scope and methods.", "A rapid review's shortcuts are justified and reported.", "A living review has resources for continuous surveillance."],
 formulas=[dict(name="Corrected covered area (overlap in overviews)", tex=r"CCA=\frac{N-r}{rc-r}", symbols={"N":"total inclusions across reviews (with repeats)","r":"unique primary studies","c":"number of reviews"})],
 worked_example="""Five reviews include 40 primary-study citations in total (N = 40) but only 25 unique primary studies (r = 25). CCA = (40 − 25)/(25×5 − 25) = 15/100 = **0.15** - overlap of 15% of the maximum possible, a 'moderate' amount by the commonly used (but conventional) bands. If instead all five reviews included the same 25 studies, N = 125 and CCA = 1.0; if no study were shared, N = r = 25 and CCA = 0.""",
 examples=[("Preclinical","Umbrella review of lifespan-extension interventions."),("Clinical","Rapid review during a health emergency."),("Ecology","Living review of conservation interventions."),("Genetics","Realist synthesis of implementation of genetic testing."),("Education","Umbrella of reading-intervention reviews.")],
 mistakes=["Ignoring overlap in an umbrella review.","Calling a rapid review 'systematic' without stating shortcuts.","Starting a living review without resources.","Applying a realist method to estimate effect sizes."],
 misconceptions=[("'An umbrella review is more reliable than the reviews it summarises.'","It inherits their biases and adds overlap issues."),("'Rapid means low quality.'","It means documented shortcuts with known risks.")],
 controversies=["Best overlap measures.", "How much streamlining is acceptable in rapid reviews.", "Sustainability of living reviews."],
 decision_tree=[("Many reviews exist on a broad question?","Umbrella review with overlap handling."),("Urgent decision?","Rapid review with documented shortcuts."),("Evidence is flowing fast?","Living review if resourced."),("Mechanism/context question?","Realist review.")],
 exercises=["Compute CCA for three overlapping reviews from a published overview.", "List the shortcuts you would accept and refuse in a rapid review.", "Draft a living-review update trigger."],
 integrity="Declare the design variant and every deviation from a full systematic review in the protocol and the report.", further=["aromataris2015","garritty2021","elliott2014","wong2013","pieper2014","pieper2022"],
 coding=dict(r='N <- 40; r <- 25; c <- 5\n(N - r) / (r * c - r)   # 0.15', python='N,r,c=40,25,5\nprint((N-r)/(r*c-r))'),
 application="**Milestone 1/2:** state why a conventional systematic review of primary studies is (or is not) the right design for your first paper.", checklist=["Design variant justified","Overlap handled","Shortcuts reported","Update plan (living)"],
 quiz=[dict(q="CCA for N = 40, r = 25, c = 5:", opts=["0.15","0.40","1.0","0.625"], ans=0, why="(40−25)/(125−25).", numeric=True),
  dict(q="The main design problem of umbrella reviews is...", opts=["Overlap of primary studies across reviews","Too few outcomes","No statistics","No search"], ans=0, why="Double counting."),
  dict(q="A rapid review should...", opts=["Report each shortcut and its likely impact","Hide shortcuts","Not use PRISMA","Use no search"], ans=0, why="Transparency."),
  dict(q="A living review needs...", opts=["Surveillance, update triggers and versioning","A single search","No protocol","Only one author"], ans=0, why="Elliott 2014."),
  dict(q="Realist reviews address...", opts=["What works for whom in which contexts and why","Pooled effect sizes","Publication bias","Cost only"], ans=0, why="Wong 2013.")])

# ===================================================================== 57
add(id=57, title="Clinical medicine and healthcare", last_verified=V, prerequisites=["Modules 9, 17, 27, 36"],
 objectives=["Use PICO, RoB 2/ROBINS-I, GRADE and PRISMA in a clinical intervention review.", "Convert relative effects into absolute effects and numbers needed to treat.", "Recognise where clinical conventions differ from laboratory-biology conventions."],
 why="Clinical meta-analysis defined many of the methods in this academy. Knowing its conventions helps you read the literature and decide which conventions to borrow for laboratory evidence.",
 plain="""Clinical reviews of interventions are framed with **PICO** (population, intervention, comparator, outcome), assess risk of bias in randomised trials with **RoB 2** (Sterne et al. 2019) and non-randomised studies with **ROBINS-I** (Sterne et al. 2016), rate the certainty of evidence per outcome with **GRADE** (Guyatt et al. 2008; Balshem et al. 2011) and report with **PRISMA 2020** (Page et al. 2021). The Cochrane Handbook (updated guidance: Cumpston et al. 2019) is the standard methods reference. Typical effect measures: risk ratio, odds ratio, hazard ratio, mean difference/SMD.

**Absolute effects matter.** A relative effect (RR 0.75) means different things at different baseline risks: with a 20% baseline risk, the absolute risk reduction is 0.20 × (1 − 0.75) = 5 percentage points, so the **number needed to treat (NNT) = 1/ARR = 20**; with a 2% baseline it is 200.""",
 intermediate="""**Outcome hierarchy:** patient-important outcomes outrank surrogate outcomes; GRADE downgrades evidence for indirectness when surrogates are used. **Multiplicity:** pre-specify primary outcomes. **Unit-of-analysis issues:** cluster and crossover trials, multi-arm trials (split shared control groups; Module 38). **Harms** are usually rarer, inconsistently reported and need rare-event methods (Module 48). **Trial registries and regulatory documents** reduce publication and outcome-reporting bias. **Clinical vs laboratory conventions:** clinical trials have standardised reporting (CONSORT), registration (ClinicalTrials.gov) and regulatory data; laboratory animal studies have ARRIVE and rarely have registered protocols - borrow the *standards* (pre-registration, risk of bias, certainty rating) and translate carefully.""",
 advanced="""Surrogate-to-clinical outcome relations, effect modification by baseline risk (the relative effect is often more constant than the absolute effect, but not always), and applicability to individual patients are persistent concerns. Network meta-analysis (Module 42) and IPD (Module 46) are widespread in clinical medicine, but their assumptions are frequently violated; look for reporting of transitivity and consistency checks.""",
 assumptions=["The relative effect transfers across baseline risks (an assumption, not a fact).", "Outcome definitions and follow-up are comparable.", "Trial-level risk of bias is assessed per outcome."],
 formulas=[dict(name="Absolute risk reduction and NNT from a relative risk", tex=r"ARR=p_c\,(1-RR),\qquad NNT=\frac1{ARR}", symbols={"p_c":"baseline (control) risk","RR":"risk ratio"})],
 worked_example="""RR = 0.75 and a control-group risk of 20%: ARR = 0.20 × 0.25 = **0.05**, NNT = **20**. With a control risk of 2%: ARR = 0.005, NNT = **200**. The same relative effect has a 10-fold different absolute impact: always present absolute effects at stated baseline risks (the Cochrane 'Summary of findings' practice).""",
 examples=[("Preclinical","Translate a lifespan effect into an absolute extension."),("Clinical","Drug trials, NNT."),("Ecology","Baseline-dependent conservation effects."),("Genetics","Absolute risk of a variant."),("Education","Absolute gain in test points.")],
 mistakes=["Reporting only relative effects.","Using one overall RoB judgement for all outcomes.","Ignoring surrogate outcomes' limits.","Pooling OR and RR as if identical."],
 misconceptions=[("'RR 0.75 means 25% of patients benefit.'","It means a 25% relative reduction in risk, with absolute impact depending on baseline risk."),("'GRADE is a risk-of-bias tool.'","It rates certainty across several domains.")],
 controversies=["Surrogate endpoints.", "Applicability to real-world patients.", "Role of observational evidence."],
 decision_tree=[("Randomised intervention trials?","RoB 2 + GRADE + PRISMA."),("Non-randomised?","ROBINS-I."),("Rare harms?","MH/Peto/GLMM and sensitivity (Module 48)."),("Relative effect found?","Compute absolute effects at stated baselines.")],
 exercises=["Compute NNT for RR 0.80 at baselines 5% and 30%.", "Complete a RoB 2 assessment for a published trial.", "Draft a 'Summary of findings' row."],
 integrity="Report absolute effects and certainty ratings; do not oversell relative effects.", further=["page2021","sterne2019rob2","sterne2016robinsi","guyatt2008","balshem2011","cumpston2019"],
 coding=dict(r='pc <- 0.20; rr <- 0.75\narr <- pc * (1 - rr); c(arr, 1 / arr)   # 0.05 20', python='pc,rr=0.20,0.75; arr=pc*(1-rr); print(arr, 1/arr)'),
 application="**Milestone 1/9:** write the PICO and the primary outcomes, and plan to report absolute effects for them.", checklist=["PICO defined","RoB per outcome","GRADE planned","Absolute effects reported"],
 quiz=[dict(q="NNT for RR 0.75 at 20% baseline risk:", opts=["20","5","4","75"], ans=0, why="1/0.05.", numeric=True),
  dict(q="NNT for the same RR at 2% baseline:", opts=["200","20","50","2"], ans=0, why="1/0.005.", numeric=True),
  dict(q="RoB 2 is used for...", opts=["Randomised trials","Cohort studies","Qualitative studies","Diagnostic accuracy"], ans=0, why="Sterne 2019."),
  dict(q="GRADE rates...", opts=["Certainty of evidence per outcome","Study quality only","Effect size","Heterogeneity"], ans=0, why="Guyatt 2008."),
  dict(q="Relative effects are...", opts=["Insufficient to judge absolute impact","Always enough","Absolute","Irrelevant"], ans=0, why="Baseline risk matters.")])

# ===================================================================== 58
add(id=58, title="Public health and epidemiology", last_verified=V, prerequisites=["Modules 9, 17, 28, 36"],
 objectives=["Plan meta-analyses of observational studies (cohort, case-control, cross-sectional) with MOOSE/ROBINS-I.", "Handle confounding, exposure heterogeneity and dose-response in synthesis.", "Interpret population-level impact measures such as population attributable fractions."],
 why="Most public-health evidence is observational. Pooled observational estimates can be precise and still biased; the review must separate precision from validity.",
 plain="""Observational studies estimate **associations** under varying adjustment and design; pooling them estimates a weighted average of *biased* effects. Use **MOOSE** (Stroup et al. 2000) for reporting and **ROBINS-I** (Sterne et al. 2016) for risk of bias (confounding, selection, classification of exposure, deviations, missing data, outcome measurement, selective reporting). Extract the **most fully adjusted** estimate that is **consistent across studies** (same covariate set where possible) and record the adjustment set; pool **adjusted** estimates (ORs/RRs/HRs) on the log scale. **Population impact** summaries combine relative risk with exposure prevalence: the population attributable fraction PAF = p(RR − 1)/(1 + p(RR − 1)).""",
 intermediate="""**Heterogeneity** is expected (different populations, exposure definitions, adjustment). Explore with pre-specified moderators and prediction intervals. **Dose-response** (Module 43) examines trends. **Bias:** residual confounding, measurement error, selective reporting, and the 'healthy-volunteer' effect; sensitivity analyses can include only low-risk-of-bias studies or alternative adjustment sets. **Causal language:** avoid 'causes' unless the design and analysis (instrumental variables, Mendelian randomisation, natural experiments) support it. **Prevalence/incidence** synthesis follows Modules 30 and 47. **Ecological studies** cannot be pooled with individual-level estimates as if equivalent.""",
 advanced="""Different adjustment sets make pooled ORs hard to interpret; some reviews pool 'minimally adjusted' and 'maximally adjusted' separately. Non-collapsibility of odds ratios means adjusted and marginal ORs differ even without confounding. PAF requires causal interpretation and a valid RR; with several exposures, PAFs do not add up.""",
 assumptions=["Adjusted estimates are comparable enough to pool (or are analysed separately).", "Exposure categories are harmonised.", "Residual confounding is considered in interpretation."],
 formulas=[dict(name="Population attributable fraction", tex=r"PAF=\frac{p\,(RR-1)}{1+p\,(RR-1)}", symbols={"p":"exposure prevalence","RR":"risk ratio (causal, adjusted)"})],
 worked_example="""Exposure prevalence p = 20% and RR = 2: PAF = 0.20×1/(1 + 0.20×1) = 0.20/1.20 = **0.1667** (about 17% of cases would be attributable to the exposure *if* the association is causal and the RR is valid). The same RR with p = 5% gives 0.05/1.05 = 0.048 - the impact depends heavily on how common the exposure is.""",
 examples=[("Preclinical","Environmental exposures in population-based animal studies."),("Clinical","Smoking and disease."),("Ecology","Exposure-outcome in field studies."),("Genetics","Gene-environment associations."),("Public health","Air pollution and mortality.")],
 mistakes=["Mixing adjusted and unadjusted estimates.","Ignoring confounding.","Pooling ecological and individual-level studies.","Reporting causal language from associations."],
 misconceptions=[("'Pooling many observational studies removes confounding.'","Confounding is a bias, not noise; it does not average out."),("'PAFs add to 100% across exposures.'","They do not.")],
 controversies=["Pooling OR vs RR.", "Combining different adjustment sets.", "Causal language in meta-analyses."],
 decision_tree=[("Cohort/case-control studies?","MOOSE + ROBINS-I; pool adjusted estimates with sensitivity analyses."),("Different exposure definitions?","Harmonise or analyse separately."),("Impact summaries needed?","PAF with stated assumptions.")],
 exercises=["Compute PAF for p = 30%, RR = 1.5.", "List the confounders for a chosen exposure-outcome pair.", "Design a sensitivity analysis restricting to low-risk-of-bias studies."],
 integrity="Describe observational findings as associations unless causal criteria are met and reported.", further=["stroup2000","sterne2016robinsi","greenland1992","borenstein2009book"],
 coding=dict(r='p <- 0.20; rr <- 2\np * (rr - 1) / (1 + p * (rr - 1))   # 0.1667', python='p,rr=0.20,2.0; print(p*(rr-1)/(1+p*(rr-1)))'),
 application="**Milestone 7/9:** record the adjustment set per study and plan a sensitivity analysis on risk of bias.", checklist=["MOOSE followed","ROBINS-I done","Adjustment sets recorded","Causal language checked"],
 quiz=[dict(q="PAF for p = 20% and RR = 2:", opts=["0.167","0.20","0.50","0.10"], ans=0, why="0.2/1.2.", numeric=True),
  dict(q="MOOSE is...", opts=["A reporting guideline for meta-analyses of observational studies","A risk-of-bias tool","A statistic","A database"], ans=0, why="Stroup 2000."),
  dict(q="Confounding in pooled observational studies...", opts=["Is not removed by pooling","Averages out","Disappears with n","Is zero"], ans=0, why="Bias persists."),
  dict(q="Which estimate to extract?", opts=["The most adjusted, with the adjustment set recorded","The crude one always","Any","The p-value"], ans=0, why="Reduce confounding; record covariates."),
  dict(q="PAFs across several exposures...", opts=["Do not simply add","Always sum to 1","Equal RR","Are probabilities of causation"], ans=0, why="Overlap.")])

# ===================================================================== 60
add(id=60, title="Molecular biology, genetics and biotechnology", last_verified=V, prerequisites=["Modules 17, 18, 27, 85"],
 objectives=["Choose effect measures for expression, genotype-phenotype and biotechnology outcomes (log fold change, lnRR, SMD).", "Handle technical vs biological replication and batch structure.", "Plan extraction from figures and supplementary data with documented uncertainty."],
 why="Molecular and genetic data are noisy, batch-sensitive and often reported as figure-only. Poor choices of effect size or unit of analysis create artefacts that no pooling method can fix.",
 plain="""Common outcomes: gene/protein **expression** (fold change, often log₂), **phenotype scores** in mutants vs controls, **enzymatic activity**, **editing efficiency** (proportion) and **yield**. For ratio-scale quantities with a positive mean, the **log response ratio** lnRR = ln(mean_treatment/mean_control) (Hedges et al. 1999) is natural; a log₂ fold change converts to lnRR by multiplying by ln 2 (log₂ FC = 1 means doubling, lnRR = 0.693). For group differences on arbitrary scales use SMD. For **proportions** (editing efficiency, survival) use logit/prevalence methods (Module 47).

**Replication:** the unit of analysis is the independent biological replicate (animals, independent cultures), not wells or technical repeats (Hurlbert 1984; Lazic 2010 and Module 85). Batch effects (plate, day, reagent lot) create dependence; record the batch structure and the number of independent experiments.""",
 intermediate="""**Extraction from figures:** digitise bar/point plots with documented tools (accuracy is generally good but depends on image quality - Drevon et al. 2016 examined agreement of one such tool) and record that values are extracted from figures. **Reporting quality:** ARRIVE 2.0 (Percie du Sert et al. 2020; reference in this library as `arrive2020`) lists items for in-vivo studies; pre-registration is rare, so assess selective reporting by comparing methods with results. **Heterogeneity** reflects genotype background, assay, tissue and time point: pre-specify moderators. **Many outcomes per study** (many genes/proteins): choose a primary outcome in the protocol or model dependence (Modules 39-40). **Omics-type outcomes** are not suitable for naive meta-analysis of thousands of features; use dedicated methods and reporting standards.""",
 advanced="""Low-expression data have mean-variance relationships that distort lnRR; consider log-transformed measurements with SMD or specialised models. Differences between knockouts, knockdowns and CRISPR edits are mechanistically distinct; do not pool them uncritically. In biotechnology (yield, titre, efficiency), process scale (flask vs bioreactor) is a major moderator; effect sizes from different scales are not exchangeable.""",
 assumptions=["Independent biological replicates define n.", "Means are positive and measured on a ratio scale for lnRR.", "Batch structure is recorded and addressed."],
 formulas=[dict(name="Log fold change conversions", tex=r"\ln RR=\ln 2\times\log_2 FC,\qquad RR=2^{\log_2 FC}", symbols={"\\log_2 FC":"log2 fold change","RR":"ratio of means"})],
 worked_example="""A gene's log₂ fold change is 1.0 (doubling): RR = 2 and lnRR = **0.6931**; log₂ FC = −0.5 corresponds to RR = 0.707 and lnRR = **−0.3466**. If the control mean is 10 and the treatment mean 12, lnRR = ln(1.2) = **0.1823** (an 18% increase). A reported p < 0.05 without n, mean and SD is *not* enough to compute an effect size and variance - record 'insufficient data' rather than guessing.""",
 examples=[("Preclinical","Knockdown effects on lifespan."),("Clinical","Biomarker fold changes."),("Plant","Transgenic yield."),("Microbiology","Editing efficiency."),("Genetics","Heterozygote vs homozygote effects.")],
 mistakes=["Counting wells as n.","Pooling knockouts with knockdowns without thought.","Ignoring batch effects.","Using lnRR for data with negative or zero means."],
 misconceptions=[("'More replicates in one plate means more n.'","Only independent replicates count."),("'Fold change of 2 means the same at all expression levels.'","Noise and detection limits vary.")],
 controversies=["lnRR vs SMD for expression data.", "Pooling across assay types."],
 decision_tree=[("Ratio-scale, positive means?","lnRR."),("Arbitrary scale?","SMD."),("Proportion?","logit/PLO."),("Figure-only data?","Digitise with documentation and sensitivity analysis.")],
 exercises=["Convert log₂ FC of 1.5 to lnRR and RR.", "Identify the independent unit in three molecular papers.", "Write extraction rules for a figure-only outcome."],
 integrity="State what the unit of replication is for every study and mark figure-extracted values.", further=["hedges1999","nakagawa2012","hurlbert1984","lazic2010","arrive2020","drevon2016"],
 coding=dict(r='log2fc <- c(1.0, -0.5)\nlog(2) * log2fc    # 0.6931 -0.3466\nlog(12 / 10)       # 0.1823', python='import math\nprint(math.log(2)*1.0, math.log(2)*-0.5, math.log(12/10))'),
 application="**Milestone 7:** choose lnRR/SMD for your outcome and write rules for technical vs biological replicates and figure-extracted values.", checklist=["Unit of replication recorded","Batch structure noted","Effect measure justified","Figure-extraction documented"],
 quiz=[dict(q="lnRR for a doubling (log₂ FC = 1):", opts=["0.693","1.0","2.0","0.5"], ans=0, why="ln 2.", numeric=True),
  dict(q="lnRR for control mean 10 and treatment mean 12:", opts=["0.182","1.2","0.2","12"], ans=0, why="ln(1.2).", numeric=True),
  dict(q="What defines n for pooling?", opts=["Independent biological replicates","Wells","Technical repeats","Images"], ans=0, why="Hurlbert; Lazic."),
  dict(q="lnRR requires...", opts=["Positive ratio-scale means","Negative means","Proportions only","Medians"], ans=0, why="Log of ratio."),
  dict(q="Digitised figure values should be...", opts=["Marked as extracted from figures","Treated as source data","Rounded to integers","Ignored"], ans=0, why="Documentation.")])

# ===================================================================== 64
add(id=64, title="Psychology and behavioural science", last_verified=V, prerequisites=["Modules 27, 29, 33, 35"],
 objectives=["Compute Hedges' g and its variance correctly and interpret it with caution.", "Appreciate replicability findings and their implications for meta-analytic estimates.", "Use reporting standards and handle dependent effects in psychological data."],
 why="Psychology popularised meta-analysis and then exposed its limits: replication projects found effects smaller than in the original literature, and meta-analyses of biased literatures can be precisely wrong.",
 plain="""The standard effect size is the **standardised mean difference** (Cohen's d; small-sample-corrected **Hedges' g**): g = J × d with J = 1 − 3/(4df − 1) (approximate form; MetaLab uses the exact gamma-function J). Other outcomes: correlations (Fisher z), proportions, regression slopes. Psychological studies often report **multiple outcomes and multiple measures per sample**, so dependence is the norm (Modules 39-40). Pigott & Polanin (2019) summarise the elements of a high-quality meta-analysis in a review; the APA's meta-analysis reporting standards complement PRISMA.""",
 intermediate="""**Replicability:** the Open Science Collaboration (2015) replicated 100 experimental and correlational studies; its abstract (PubMed) reports that replication effects were about half the magnitude of the original effects, and that 97% of the original studies but 36% of the replications had statistically significant results. Kvarven et al. (2019) compared 15 meta-analyses with large preregistered multi-laboratory replications on the same topics; per the abstract, meta-analytic effect sizes differed significantly from the replication effect sizes for 12 of the 15 pairs and were on average almost three times as large, and three bias-correction methods did not substantively improve the meta-analytic results. Implication: with publication bias and flexible analyses, a meta-analytic mean may overestimate; always include bias analyses (Module 49) and report them as sensitivity analyses. **Measurement:** different scales for the same construct are combined via SMD, assuming comparable constructs and reliabilities; **moderators** (population, task) need prespecification. **Small-sample correction:** with n = 5 per group J ≈ 0.90, so the difference between d and g is not trivial.""",
 advanced="""Registered reports and preregistered multi-site replications provide less biased estimates but cover few effects. Bayesian and selection-model approaches (Modules 41, 49) can help; none rescue a biased literature. Effect sizes for within-subject designs require the pre-post correlation, often unreported (assume and vary it).""",
 assumptions=["Constructs measured by different scales are comparable.", "Independent samples (or dependence modelled).", "Selective reporting is assessed."],
 formulas=[dict(name="Hedges' g", tex=r"g=J\,d,\quad J\approx1-\frac{3}{4\,df-1},\quad d=\frac{\bar x_1-\bar x_2}{s_p}", symbols={"df":"n1+n2-2","s_p":"pooled SD"})],
 worked_example="""Two groups of 20, d = 0.5 (means differ by 0.5 pooled SD): J (exact) = **0.9801**, g = **0.4901**, variance (Larry-Stephens form) = **0.1030**. With only 5 per group and a 0.02 difference over SD 0.01 (d = 2.0): J = 0.9027, g = **1.805** - a large standardised effect arising from tiny seed-to-seed variability, a reminder that SMDs from very small or very low-variance samples can be inflated and fragile.""",
 examples=[("Preclinical","Behavioural tests in animals."),("Clinical","Psychotherapy trials."),("Ecology","Behaviour experiments."),("Genetics","Behavioural phenotypes."),("Education","Learning interventions.")],
 mistakes=["Reporting d instead of g for small samples.","Ignoring multiple measures per sample.","Not checking publication bias.","Treating replications as redundant."],
 misconceptions=[("'A meta-analysis of many studies is the final word.'","It can inherit and amplify bias."),("'g and d are interchangeable.'","They differ noticeably for small samples.")],
 controversies=["Meta-analysis vs multi-lab replications.", "Handling flexible analyses."],
 decision_tree=[("Group comparison?","Hedges' g."),("Multiple outcomes per sample?","Multilevel/RVE."),("Plan to claim robustness?","Bias analyses + sensitivity.")],
 exercises=["Compute g and variance for n = 12 per group, d = 0.8.", "List sources of selective reporting in a psychology literature.", "Pre-specify one moderator and justify it."],
 integrity="Report bias analyses and note replicability evidence; avoid language implying certainty.", further=["osc2015","kvarven2019","pigott2019","borenstein2009book","hedges1981"],
 coding=dict(r='library(metafor)\nd <- escalc("SMD", m1i = 10.5, sd1i = 1, n1i = 20, m2i = 10, sd2i = 1, n2i = 20)\nround(c(d$yi, d$vi), 4)   # 0.4901 0.1030', python='from metalab import stats as S\nprint(S.smd(10.5,1,20,10,1,20))'),
 application="**Milestone 7/9:** if your questions touch behaviour, pre-specify bias analyses and multiple-outcome handling.", checklist=["g (not d) for small n","Dependence modelled","Bias analyses planned","Moderators pre-specified"],
 quiz=[dict(q="Hedges' g for d = 0.5 with 20 per group (exact J):", opts=["0.490","0.5","0.45","0.55"], ans=0, why="0.5×0.9801.", numeric=True),
  dict(q="Variance of g in that example:", opts=["0.103","0.5","0.01","1.0"], ans=0, why="Computed by smd().", numeric=True),
  dict(q="Replication projects suggest that...", opts=["Published effects can be overestimated","All effects are confirmed","Effects are always larger","Meta-analyses are always accurate"], ans=0, why="Open Science Collaboration 2015."),
  dict(q="J (small-sample correction) is closest to 1 when...", opts=["Sample is large","Sample is small","Effect is large","SD is large"], ans=0, why="J→1."),
  dict(q="Multiple measures per sample require...", opts=["Modelling dependence","Ignoring it","Dropping outcomes","Larger n"], ans=0, why="Modules 39-40.")])

# ===================================================================== 66
add(id=66, title="Nutrition, food science and exercise", last_verified=V, prerequisites=["Modules 17, 28, 43, 58"],
 objectives=["Handle dose and increment scales (per 10 g/day, per serving) when pooling.", "Account for measurement error and confounding in nutritional epidemiology and for crossover designs in feeding/exercise trials.", "Match the study design (RCT vs cohort) to the strength of conclusions."],
 why="Nutritional exposures are measured with error, correlated with lifestyle and expressed on inconsistent scales. Without harmonising the dose scale and the design, pooled results are uninterpretable.",
 plain="""**Rescale carefully.** Cohort studies report RRs per different increments (per 25 g/day, per serving). Under the log-linear assumption, rescale the log RR proportionally: RR per 10 g = RR per 25 g raised to the power 10/25. With RR = 1.10 per 25 g, RR per 10 g = 1.10^(0.4) = **1.0389**. Check that the trend is plausibly linear over the range (Module 43). **Feeding and exercise trials** are often **crossover** or repeated-measures: the standard error of a paired difference depends on the within-person correlation, usually unreported; impute with sensitivity analyses (Module 38). **Dietary assessment** (food-frequency questionnaires) has substantial measurement error that attenuates associations; energy adjustment and substitution (replacing one food with another) change the meaning of an estimate.""",
 intermediate="""**Design hierarchy:** controlled feeding trials provide short-term biomarker effects; long-term outcomes mostly come from cohorts with residual confounding. **Reporting:** PRISMA/MOOSE; for nutrition-specific extensions use the relevant guideline versions of your field. **Heterogeneity** arises from food definitions (processed vs unprocessed), preparation, baseline intake and genotype. **Units:** convert to common units (g/day, kcal/day) and document each conversion. **Exercise studies:** dose = frequency × intensity × duration; define a comparable dose metric or analyse categories. **Exposure windows** and adherence differ across studies; per-protocol vs intention-to-treat effects are different estimands.""",
 advanced="""Substitution analyses need covariance of the replaced and added components; summary data rarely permit this. Measurement-error corrections need validation substudies. Dose-response curves in nutrition are often non-linear (J-shaped, plateau); a linear pooled slope may misrepresent them.""",
 assumptions=["Log-linearity over the exposure range for rescaling.", "Units are harmonised.", "Within-person correlation assumed for crossover data is varied in sensitivity analysis."],
 formulas=[dict(name="Rescaling a log-linear relative risk", tex=r"RR_{\Delta_2}=RR_{\Delta_1}^{\,\Delta_2/\Delta_1}", symbols={"\\Delta":"increment size (e.g. 25 g/day)"})],
 worked_example="""A cohort reports RR = 1.10 per 25 g/day. Per 10 g/day: 1.10^(10/25) = **1.0389**; per 50 g/day: 1.10² = **1.21**. If the true relation is J-shaped, such extrapolation is wrong; always check the range of observed intakes. For a crossover with SD of the paired differences unreported, vary the assumed correlation (0.3, 0.5, 0.7) and show how the SE of the mean difference changes.""",
 examples=[("Preclinical","Diet restriction regimens in flies/rodents."),("Clinical","Dietary supplements."),("Ecology","Nutrient additions."),("Genetics","Nutrigenomics."),("Exercise","Training dose-response.")],
 mistakes=["Pooling RRs per different increments.","Assuming linearity beyond observed intakes.","Ignoring measurement error.","Ignoring the substitution comparator."],
 misconceptions=[("'RR per serving equals RR per gram.'","They differ by the increment size."),("'Cohort estimates equal causal effects.'","Residual confounding is common.")],
 controversies=["Value of cohort vs RCT evidence in nutrition.", "Substitution models."],
 decision_tree=[("Different increments?","Rescale on the log scale and check linearity."),("Crossover?","Use paired SD or assumed correlation with sensitivity."),("Non-linear?","Spline-based dose-response (external).")],
 exercises=["Convert RR 1.25 per serving (80 g) to per 100 g.", "Show how the SE of a crossover difference depends on the assumed correlation.", "Define the comparator in a substitution analysis."],
 integrity="Document unit conversions and linearity assumptions; avoid causal claims from observational nutrition data.", further=["greenland1992","orsini2012","borenstein2009book","stroup2000"],
 coding=dict(r='1.10^(10 / 25)    # 1.0389\n1.10^(50 / 25)    # 1.21', python='print(1.10**(10/25), 1.10**(50/25))'),
 application="**Milestone 7:** if exposures vary in units/increments, write a conversion table in the extraction form.", checklist=["Common units","Increment rescaling","Crossover handled","Linearity checked"],
 quiz=[dict(q="RR per 10 g/day if RR per 25 g/day is 1.10:", opts=["1.039","1.04 per g","1.10","1.25"], ans=0, why="1.10^(0.4).", numeric=True),
  dict(q="Rescaling an RR by increment assumes...", opts=["Log-linearity","Normality of the diet","No confounding","Zero heterogeneity"], ans=0, why="Proportional log RR."),
  dict(q="Crossover trials need...", opts=["The within-person correlation or paired SD","Nothing special","A larger n","A different p-value"], ans=0, why="Paired design."),
  dict(q="Food-frequency questionnaire error typically...", opts=["Attenuates associations","Exaggerates them always","Has no effect","Removes confounding"], ans=0, why="Measurement error."),
  dict(q="Substitution analyses change...", opts=["The meaning of the comparator","The sample size","The p-value only","Nothing"], ans=0, why="What replaces what.")])

# ===================================================================== 67
add(id=67, title="Economics, business and policy", last_verified=V, prerequisites=["Modules 29, 33, 39, 49"],
 objectives=["Meta-analyse partial correlations and elasticities and use meta-regression to explain heterogeneity.", "Recognise that economics meta-analyses often have large heterogeneity and many dependent estimates.", "Apply funnel/PET-type small-study analyses as sensitivity checks."],
 why="Economics and policy evidence typically consists of many regression estimates per paper with different specifications. Meta-regression analysis (Stanley and colleagues) is a standard framework, with its own conventions and pitfalls.",
 plain="""Primary studies report regression coefficients with different units and specifications, so a common effect size is needed: the **partial correlation** r = t/√(t² + df) computed from the reported t-statistic and its degrees of freedom is widely used; **elasticities** (percentage change per percentage change) and **standardised coefficients** are alternatives. Because studies contribute **many estimates** (different specifications, subsamples), the data are hierarchical: cluster by study and use multilevel/RVE methods (Modules 39-40). **Meta-regression analysis** regresses effects on moderators (country, period, estimation method, data type) and on the standard error to examine small-study/publication selection (Stanley & Doucouliagos' funnel-asymmetry approach; PET-type regression - Module 49).""",
 intermediate="""**Heterogeneity** is usually very large (I² often > 90%); focus on moderators and on prediction intervals. **Specification search**: authors choose among specifications; extracting only the 'preferred' estimate risks selection; extract all or pre-specify rules. **Weights:** inverse-variance weights favour studies reporting many small-SE estimates; consider cluster-robust weights. **Policy relevance:** external validity across countries/periods is limited; report ranges. **Grey literature** (working papers) matters because journal publication selects on significance. **Data and code availability:** replicable extraction is easier when replication packages exist.""",
 advanced="""PET-PEESE-type estimates were developed for such data but their performance degrades with heterogeneity and dependence; use as sensitivity analyses (MetaLab benchmarks PET/PEESE against lm). Endogeneity in primary studies (omitted variables, reverse causation) is not fixed by pooling. Different dependent-variable transformations (levels vs logs) change elasticities.""",
 assumptions=["t-statistics and df are correctly reported (and not manipulated by robust SE conventions).", "Dependent estimates are clustered by study.", "Small-study regressions are interpreted as sensitivity analyses."],
 formulas=[dict(name="Partial correlation from a regression t-statistic", tex=r"r=\frac{t}{\sqrt{t^2+df}},\qquad \mathrm{Var}(r)\approx\frac{(1-r^2)^2}{df}", symbols={"t":"reported t-statistic","df":"degrees of freedom of the regression"})],
 worked_example="""A coefficient has t = 2.5 with df = 40: partial correlation r = 2.5/√(6.25 + 40) = 2.5/6.8007 = **0.3676**; approximate variance (1 − 0.1351)²/40 = **0.0187**, SE **0.137**. If the same estimate appears in six specifications of one paper, treating them as six independent effects would count the paper six times: cluster by study.""",
 examples=[("Preclinical","Policy-related animal welfare interventions (rare)."),("Clinical","Health economics evaluations."),("Ecology","Payments for ecosystem services."),("Policy","Minimum-wage employment effects."),("Education","Returns to schooling.")],
 mistakes=["Counting specifications as independent.","Extracting only significant estimates.","Pooling levels and log specifications.","Ignoring grey literature."],
 misconceptions=[("'More estimates per paper means more information.'","They are correlated."),("'A large meta-analysis implies a causal effect.'","Endogeneity persists.")],
 controversies=["Weighting schemes.", "Value of PET-PEESE.", "Pooling heterogenous specifications."],
 decision_tree=[("Regression coefficients with t and df?","Partial correlations."),("Many estimates per study?","Cluster + RVE."),("Concern for selection?","Funnel/PET sensitivity analyses.")],
 exercises=["Convert t = 3.1, df = 80 to r and its variance.", "Write rules for choosing among specifications.", "Explain why I² > 90% is common here."],
 integrity="Extract according to pre-specified rules and report all analyses; do not cherry-pick specifications.", further=["stanley2008","borenstein2009book","cheung2019","pigott2019"],
 coding=dict(r='t <- 2.5; df <- 40\nr <- t / sqrt(t^2 + df); c(r, (1 - r^2)^2 / df)   # 0.3676 0.0187', python='import math\nt,df=2.5,40; r=t/math.sqrt(t*t+df); print(r, (1-r*r)**2/df)'),
 application="**Milestone 7/9:** define the extraction rule for multiple estimates per study before extracting.", checklist=["Effect size defined","Specifications rule","Clustering","Selection sensitivity"],
 quiz=[dict(q="Partial correlation for t = 2.5, df = 40:", opts=["0.368","0.5","0.25","0.062"], ans=0, why="2.5/√46.25.", numeric=True),
  dict(q="Why cluster by study?", opts=["Estimates within a paper are dependent","Papers differ in length","To increase n","To lower heterogeneity"], ans=0, why="Shared data/specification."),
  dict(q="I² in economics meta-analyses is often...", opts=["Very high","Zero","Moderate","Negative"], ans=0, why="Heterogeneity."),
  dict(q="PET/PEESE should be used as...", opts=["Sensitivity analyses","Definitive corrections","Replacements for tests","Effect sizes"], ans=0, why="Module 49."),
  dict(q="Pooling does not fix...", opts=["Endogeneity in primary studies","Heterogeneity","Weights","Variance"], ans=0, why="Bias persists.")])

# ===================================================================== 68
add(id=68, title="Engineering and computer science", last_verified=V, prerequisites=["Modules 9, 17, 27, 36"],
 objectives=["Adapt systematic-review methods to software engineering and computational experiments.", "Identify the independent unit (dataset, seed, run) and handle variance across random seeds.", "Report computational experiments reproducibly."],
 why="Computational and engineering studies have systematic review traditions (Kitchenham) but also unique pitfalls: tiny variance from fixed seeds, shared benchmarks, and results that depend on implementation details.",
 plain="""**Systematic literature reviews in software engineering** follow protocols similar to health reviews (Kitchenham & Brereton), with discipline-specific databases (IEEE Xplore, ACM Digital Library) and often with qualitative or mapping syntheses rather than meta-analysis. When quantitative synthesis is possible (performance differences, defect rates, effort estimates), **define the unit of analysis**: the dataset/benchmark, not the number of random seeds; multiple runs of one method on one dataset share the same data and implementation and are not independent replicates of the *comparison*. **Effect measures:** standardised mean differences of performance across datasets, log ratios of error, win-rates (sign tests) - always accompanied by the variance *across datasets*.""",
 intermediate="""**Seed variability:** the SD across seeds measures algorithmic randomness, not the uncertainty about which method is better *in general*. Using it as the SD in an SMD produces enormous standardised effects for trivial differences (means 0.80 vs 0.78, SD 0.01, 5 seeds → g = 1.81). **Pairing:** methods compared on the same datasets are paired; ignoring pairing mis-estimates variance. **Reproducibility:** report code versions, hardware, seeds, hyperparameter search budgets (unequal tuning is a frequent bias), and make artefacts available; pre-registration of computational experiments is rare. **Threats to validity** (construct, internal, external) are the common vocabulary; map them to risk-of-bias judgements. **Grey literature** (arXiv, tech reports) is important and often unrefereed: record that status.""",
 advanced="""Benchmark leakage, data contamination and overfitting to public test sets inflate performance; synthesis across papers inherits them. Performance metrics (accuracy, F1, AUC) have different properties and base-rate sensitivity; convert with care or analyse separately. Meta-analysis in engineering is limited by incompatible metrics; narrative synthesis with transparent tables is often the right output.""",
 assumptions=["The unit of replication (dataset or independent experiment) is defined.", "Performance metrics are comparable across studies.", "Tuning effort is comparable or recorded."],
 formulas=[dict(name="Paired comparison across datasets", tex=r"\bar d=\frac1m\sum_{k=1}^m(a_k-b_k),\qquad SE=\frac{s_d}{\sqrt m}", symbols={"a_k,b_k":"performance of methods A and B on dataset k","m":"number of datasets"})],
 worked_example="""Method A has mean accuracy 0.80 and method B 0.78, each with SD 0.01 over 5 random seeds on ONE dataset: Hedges' g = **1.805** (J = 0.9027), but this describes seed noise on one dataset and says nothing about general superiority. Evaluated on m = 10 datasets with mean paired difference 0.02 and SD of differences 0.05: SE = 0.05/√10 = **0.0158**, t = 1.26 (9 df) - far less impressive, and the right uncertainty for the generalisation question.""",
 examples=[("Preclinical","In-silico model comparisons."),("Clinical","Machine-learning diagnostic tools."),("Ecology","Species-distribution models."),("Genetics","Variant-calling pipelines."),("Software","Defect prediction.")],
 mistakes=["Using seed variance as the comparison variance.","Ignoring unequal tuning budgets.","Pooling incompatible metrics.","Not reporting code/seeds."],
 misconceptions=[("'More random seeds means more evidence of superiority.'","It reduces seed noise on the same dataset, not dataset-to-dataset variance."),("'A public benchmark gives unbiased tests.'","Leakage and overfitting occur.")],
 controversies=["Statistical testing in ML comparisons.", "Meta-analysis feasibility with heterogeneous metrics."],
 decision_tree=[("Comparable metric and datasets?","Paired effects across datasets."),("Different metrics?","Narrative synthesis/mapping."),("Seeds only?","Not a comparison of methods in general.")],
 exercises=["Compute the SE for a paired comparison across 12 datasets given mean difference and SD.", "List the information needed to reproduce one experiment.", "Design a data-extraction form for a computational SR."],
 integrity="Report seeds, code versions and tuning budgets; do not present within-dataset noise as evidence of general superiority.", further=["kitchenham2009","wilson2017","sandve2013"],
 coding=dict(r='library(metafor)\nd <- escalc("SMD", m1i = 0.80, sd1i = 0.01, n1i = 5, m2i = 0.78, sd2i = 0.01, n2i = 5)\nround(c(d$yi, d$vi), 3)   # 1.805 0.563\nsd_d <- 0.05; m <- 10; sd_d / sqrt(m)   # 0.0158', python='from metalab import stats as S\nimport math\nprint(S.smd(0.80,0.01,5,0.78,0.01,5)[:2], 0.05/math.sqrt(10))'),
 application="**Milestone 1/7:** if you include computational outcomes, define the unit of replication and the metrics in the protocol.", checklist=["Unit of replication defined","Pairing handled","Tuning budgets recorded","Artefacts available"],
 quiz=[dict(q="Hedges' g for 0.80 vs 0.78 (SD 0.01, n = 5 each):", opts=["1.805","0.02","2.0","0.5"], ans=0, why="J×d = 0.9027×2.", numeric=True),
  dict(q="Why is this g misleading as a comparison of methods?", opts=["It reflects seed noise on one dataset, not generalisation","It is too small","It is negative","It ignores p"], ans=0, why="Wrong unit."),
  dict(q="SE of a mean paired difference with SD 0.05 over 10 datasets:", opts=["0.0158","0.05","0.5","0.005"], ans=0, why="0.05/√10.", numeric=True),
  dict(q="Kitchenham's contribution was...", opts=["Adapting systematic review methods to software engineering","Inventing I²","Defining SMD","GRADE"], ans=0, why="Kitchenham 2009."),
  dict(q="Hyperparameter tuning budgets should be...", opts=["Reported and comparable across methods","Hidden","Irrelevant","Maximised for one method"], ans=0, why="Fairness.")])
